using ProMaxx2.QA.Domain.Identity;using ProMaxx2.QA.Application.Projects;
namespace ProMaxx2.QA.Application.Identity;
public sealed record UserDto(Guid UserId,string Username,string DisplayName,string?Email,bool IsActive,DateTime?LastLoginAt,IReadOnlyList<string>Roles,IReadOnlyList<Guid>AssignedProjectIds);public sealed record CreateUserRequest(string Username,string DisplayName,string?Email,string Password,IReadOnlyList<Guid>?RoleIds);public sealed record UpdateUserRequest(string DisplayName,string?Email,bool IsActive);public sealed record ResetPasswordRequest(string NewPassword);public sealed record AssignRolesRequest(IReadOnlyList<Guid>RoleIds);public sealed record AssignProjectsRequest(IReadOnlyList<Guid>ProjectIds);
public sealed record RoleDto(Guid RoleId,string RoleCode,string RoleName,string?Description,bool IsActive,IReadOnlyList<string>Permissions);public sealed record PermissionDto(Guid PermissionId,string PermissionCode,string PermissionName,string?ModuleArea);public sealed record CreateRoleRequest(string RoleCode,string RoleName,string?Description);public sealed record UpdateRoleRequest(string RoleName,string?Description);public sealed record AssignPermissionsRequest(IReadOnlyList<Guid>PermissionIds);
public interface IAdministrationRepository{Task<IReadOnlyList<UserDto>>UsersAsync(CancellationToken ct);Task<User?>FindUserAsync(Guid id,CancellationToken ct);Task<bool>UsernameExistsAsync(string username,CancellationToken ct);Task AddUserAsync(User user,CancellationToken ct);Task AssignRolesAsync(Guid userId,IReadOnlyList<Guid>roleIds,CancellationToken ct);Task AssignProjectsAsync(Guid userId,IReadOnlyList<Guid>projectIds,CancellationToken ct);Task<IReadOnlyList<RoleDto>>RolesAsync(CancellationToken ct);Task<Role?>FindRoleAsync(Guid id,CancellationToken ct);Task<bool>RoleCodeExistsAsync(string code,CancellationToken ct);Task AddRoleAsync(Role role,CancellationToken ct);Task AssignPermissionsAsync(Guid roleId,IReadOnlyList<Guid>permissionIds,CancellationToken ct);Task<IReadOnlyList<PermissionDto>>PermissionsAsync(CancellationToken ct);Task SaveAsync(CancellationToken ct);}
public sealed class AdministrationService(IAdministrationRepository repository,IPasswordService passwords)
{
 public Task<IReadOnlyList<UserDto>>UsersAsync(CancellationToken ct)=>repository.UsersAsync(ct);public async Task<UserDto>CreateUserAsync(CreateUserRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Username)||r.Password.Length<8)throw new ArgumentException("Username is required and password must contain at least 8 characters.");if(await repository.UsernameExistsAsync(r.Username.Trim(),ct))throw new DuplicateCodeException("Username already exists.");var user=new User(r.Username,r.DisplayName,r.Email,passwords.Hash(r.Password));await repository.AddUserAsync(user,ct);await repository.SaveAsync(ct);if(r.RoleIds?.Count>0){await repository.AssignRolesAsync(user.UserId,r.RoleIds,ct);await repository.SaveAsync(ct);}return(await repository.UsersAsync(ct)).Single(x=>x.UserId==user.UserId);}public async Task<UserDto>UpdateUserAsync(Guid id,UpdateUserRequest r,CancellationToken ct){var user=await repository.FindUserAsync(id,ct)??throw new EntityNotFoundException("User not found.");user.Update(r.DisplayName,r.Email);if(r.IsActive)user.Activate();else user.Deactivate();await repository.SaveAsync(ct);return(await repository.UsersAsync(ct)).Single(x=>x.UserId==id);} public async Task AssignRolesAsync(Guid id,AssignRolesRequest r,CancellationToken ct){_=await repository.FindUserAsync(id,ct)??throw new EntityNotFoundException("User not found.");await repository.AssignRolesAsync(id,r.RoleIds,ct);await repository.SaveAsync(ct);}public async Task AssignProjectsAsync(Guid id,AssignProjectsRequest r,CancellationToken ct){_=await repository.FindUserAsync(id,ct)??throw new EntityNotFoundException("User not found.");await repository.AssignProjectsAsync(id,r.ProjectIds,ct);await repository.SaveAsync(ct);}public async Task ResetPasswordAsync(Guid id,string password,CancellationToken ct){if(password.Length<8)throw new ArgumentException("Password must contain at least 8 characters.");var user=await repository.FindUserAsync(id,ct)??throw new EntityNotFoundException("User not found.");user.ResetPassword(passwords.Hash(password));await repository.SaveAsync(ct);}
 public Task<IReadOnlyList<RoleDto>>RolesAsync(CancellationToken ct)=>repository.RolesAsync(ct);public Task<IReadOnlyList<PermissionDto>>PermissionsAsync(CancellationToken ct)=>repository.PermissionsAsync(ct);public async Task<RoleDto>CreateRoleAsync(CreateRoleRequest r,CancellationToken ct){var code=r.RoleCode.Trim().ToUpperInvariant();if(await repository.RoleCodeExistsAsync(code,ct))throw new DuplicateCodeException("Role code already exists.");var role=new Role(code,r.RoleName,r.Description);await repository.AddRoleAsync(role,ct);await repository.SaveAsync(ct);return(await repository.RolesAsync(ct)).Single(x=>x.RoleId==role.RoleId);}public async Task<RoleDto>UpdateRoleAsync(Guid id,UpdateRoleRequest r,CancellationToken ct){var role=await repository.FindRoleAsync(id,ct)??throw new EntityNotFoundException("Role not found.");role.Update(r.RoleName,r.Description);await repository.SaveAsync(ct);return(await repository.RolesAsync(ct)).Single(x=>x.RoleId==id);}public async Task AssignPermissionsAsync(Guid id,AssignPermissionsRequest r,CancellationToken ct){_=await repository.FindRoleAsync(id,ct)??throw new EntityNotFoundException("Role not found.");await repository.AssignPermissionsAsync(id,r.PermissionIds,ct);await repository.SaveAsync(ct);}
}
